#!/usr/bin/env node
/**
 * axe-core audit probe (kept out of the repo).
 * Usage: node /tmp/audit/a11y.mjs http://127.0.0.1:8787 [width] [height] [path]
 */
import { spawn } from 'node:child_process';
import { readFile, writeFile, mkdir } from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';

const BASE = (process.argv[2] || 'http://127.0.0.1:8787').replace(/\/$/, '');
const W = Number(process.argv[3] || 1440);
const H = Number(process.argv[4] || 960);
const ROUTE = process.argv[5] || '/';
const AXE = await readFile('/tmp/axe/package/axe.min.js', 'utf8');

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const PORT = 9333;

class CDP {
  constructor(ws) {
    this.ws = ws; this.id = 0; this.pending = new Map();
    ws.addEventListener('message', (e) => {
      const m = JSON.parse(e.data);
      if (m.id && this.pending.has(m.id)) {
        const { resolve, reject } = this.pending.get(m.id);
        this.pending.delete(m.id);
        if (m.error) reject(new Error(m.error.message)); else resolve(m.result);
      }
    });
  }
  send(method, params = {}) {
    const id = ++this.id;
    return new Promise((resolve, reject) => {
      this.pending.set(id, { resolve, reject });
      this.ws.send(JSON.stringify({ id, method, params }));
      setTimeout(() => { if (this.pending.delete(id)) reject(new Error(method + ' timed out')); }, 60000);
    });
  }
  async eval(expression) {
    const { result, exceptionDetails } = await this.send('Runtime.evaluate', { expression, returnByValue: true, awaitPromise: true });
    if (exceptionDetails) throw new Error(exceptionDetails.exception?.description || exceptionDetails.text);
    return result?.value;
  }
}

const chrome = spawn('chromium', [
  '--headless=new', '--no-sandbox', '--disable-gpu', '--disable-dev-shm-usage', '--hide-scrollbars',
  `--window-size=${W},${H}`, `--remote-debugging-port=${PORT}`,
  `--user-data-dir=${path.join(os.tmpdir(), 'axe-profile-' + process.pid)}`, 'about:blank',
], { stdio: ['ignore', 'ignore', 'ignore'] });

let info;
for (let i = 0; i < 60; i++) {
  try { const r = await fetch(`http://127.0.0.1:${PORT}/json/version`); if (r.ok) { info = await r.json(); break; } } catch {}
  await sleep(500);
}
if (!info) { chrome.kill('SIGKILL'); throw new Error('chrome did not start'); }

const targets = await (await fetch(`http://127.0.0.1:${PORT}/json/list`)).json();
const page = targets.find((t) => t.type === 'page');
const ws = new WebSocket(page.webSocketDebuggerUrl);
await new Promise((res) => ws.addEventListener('open', res, { once: true }));
const cdp = new CDP(ws);
await cdp.send('Page.enable');
await cdp.send('Runtime.enable');
await cdp.send('Emulation.setDeviceMetricsOverride', { width: W, height: H, deviceScaleFactor: 1, mobile: W < 600 });

await cdp.send('Page.navigate', { url: BASE + ROUTE });
await sleep(6000);
// wait until the seed arrives and the results list is no longer busy
for (let i = 0; i < 60; i++) {
  const ready = await cdp.eval(`(() => document.querySelectorAll('#result-list li').length > 0 && document.querySelector('#result-list')?.getAttribute('aria-busy') !== 'true')()`).catch(() => false);
  if (ready) break;
  await sleep(500);
}
await sleep(1500);
const url = await cdp.eval('location.href');
const rows = await cdp.eval(`document.querySelectorAll('#result-list > li').length`);
await cdp.eval(AXE);
const res = await cdp.eval(`axe.run(document, { runOnly: { type: 'tag', values: ['wcag2a','wcag2aa','wcag21a','wcag21aa','wcag22aa','best-practice'] }, resultTypes: ['violations'] }).then(r => r.violations.map(v => ({ id: v.id, impact: v.impact, help: v.help, tags: v.tags, nodes: v.nodes.slice(0, 4).map(n => ({ target: n.target.join(' '), summary: (n.failureSummary||'').split('\\n').slice(0,3).join(' | ') })) }))) `);
console.log(`URL ${url}  ${W}x${H}  rows=${rows}`);
console.log(JSON.stringify(res, null, 2));

// also a coarse tab-order / focus-visibility probe
const focusProbe = await cdp.eval(`(() => {
  const out = [];
  const nodes = [...document.querySelectorAll('a[href], button:not([disabled]), input:not([disabled]), select:not([disabled]), summary, [tabindex]:not([tabindex="-1"])')];
  for (const n of nodes) {
    if (n.closest('[hidden]') || n.offsetParent === null) continue;
    out.push(n.tagName.toLowerCase() + (n.id ? '#' + n.id : '') + (n.className && typeof n.className === 'string' ? '.' + n.className.split(' ').filter(Boolean).slice(0,2).join('.') : ''));
  }
  return out.length + ' focusables | ' + out.slice(0, 60).join(' > ');
})()`);
console.log('FOCUS ORDER:', focusProbe);

await cdp.send('Page.captureScreenshot', { format: 'png' }).then(async ({ data }) => {
  await mkdir('/tmp/audit/shots', { recursive: true });
  await writeFile(`/tmp/audit/shots/axe-${W}x${H}${ROUTE.replace(/\W+/g, '_')}.png`, Buffer.from(data, 'base64'));
});
ws.close();
chrome.kill('SIGKILL');

