/**
 * axe-core audit in several UI states (probe, kept out of the repo).
 * Usage: node /tmp/audit/axe-multi.mjs [baseUrl] [width] [height]
 */
import { spawn } from 'node:child_process';
import { readFile, writeFile, mkdir } from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';

const BASE = (process.argv[2] || 'http://127.0.0.1:8787').replace(/\/$/, '');
const W = Number(process.argv[3] || 1440);
const H = Number(process.argv[4] || 960);
const AXE = await readFile('/tmp/axe/package/axe.min.js', 'utf8');
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const PORT = 9336 + Math.floor(Math.random() * 20);

class CDP {
  constructor(ws) {
    this.ws = ws; this.id = 0; this.pending = new Map();
    ws.addEventListener('message', (e) => {
      const m = JSON.parse(e.data);
      if (m.id && this.pending.has(m.id)) {
        const { resolve, reject } = this.pending.get(m.id); this.pending.delete(m.id);
        if (m.error) reject(new Error(m.error.message)); else resolve(m.result);
      }
    });
  }
  send(method, params = {}) {
    const id = ++this.id;
    return new Promise((resolve, reject) => {
      this.pending.set(id, { resolve, reject });
      this.ws.send(JSON.stringify({ id, method, params }));
      setTimeout(() => { if (this.pending.delete(id)) reject(new Error(method + ' timed out')); }, 60000);
    });
  }
  async eval(expression) {
    const r = await this.send('Runtime.evaluate', { expression, returnByValue: true, awaitPromise: true });
    if (r.exceptionDetails) throw new Error(r.exceptionDetails.exception?.description || r.exceptionDetails.text);
    return r.result?.value;
  }
  async click(selector, index = 0) {
    const box = await this.eval(`(() => { const n = document.querySelectorAll(${JSON.stringify(selector)})[${index}]; if (!n) return null; n.scrollIntoView({block:'center',behavior:'instant'}); const r = n.getBoundingClientRect(); return {x: r.left + r.width/2, y: r.top + r.height/2}; })()`);
    if (!box) throw new Error('no element ' + selector);
    const common = { x: Math.round(box.x), y: Math.round(box.y), button: 'left', clickCount: 1 };
    await this.send('Input.dispatchMouseEvent', { type: 'mouseMoved', ...common });
    await this.send('Input.dispatchMouseEvent', { type: 'mousePressed', ...common });
    await this.send('Input.dispatchMouseEvent', { type: 'mouseReleased', ...common });
  }
  async shot(name) {
    const { data } = await this.send('Page.captureScreenshot', { format: 'png' });
    await mkdir('/tmp/audit/shots', { recursive: true });
    await writeFile(`/tmp/audit/shots/${name}.png`, Buffer.from(data, 'base64'));
  }
}

const chrome = spawn('chromium', ['--headless=new','--no-sandbox','--disable-gpu','--disable-dev-shm-usage','--hide-scrollbars',`--window-size=${W},${H}`,`--remote-debugging-port=${PORT}`,`--user-data-dir=${path.join(os.tmpdir(),'axem-'+process.pid)}`,'about:blank'], { stdio: 'ignore' });
for (let i = 0; i < 60; i++) { try { const r = await fetch(`http://127.0.0.1:${PORT}/json/version`); if (r.ok) break; } catch {} await sleep(500); }
const targets = await (await fetch(`http://127.0.0.1:${PORT}/json/list`)).json();
const ws = new WebSocket(targets.find((t) => t.type === 'page').webSocketDebuggerUrl);
await new Promise((res) => ws.addEventListener('open', res, { once: true }));
const cdp = new CDP(ws);
await cdp.send('Page.enable'); await cdp.send('Runtime.enable');
await cdp.send('Emulation.setDeviceMetricsOverride', { width: W, height: H, deviceScaleFactor: 1, mobile: W < 600 });

async function runAxe(label) {
  await cdp.eval(AXE);
  const violations = await cdp.eval(`axe.run(document, { runOnly: { type: 'tag', values: ['wcag2a','wcag2aa','wcag21a','wcag21aa','wcag22aa','best-practice'] }, resultTypes: ['violations'] }).then(r => r.violations.map(v => ({ id: v.id, impact: v.impact, help: v.help, count: v.nodes.length, nodes: v.nodes.slice(0,6).map(n => ({ t: n.target.join(' '), html: (n.html||'').slice(0,140) })) })))`);
  console.log(`\n===== ${label} (${await cdp.eval('location.href')}) violations: ${violations.length}`);
  for (const v of violations) {
    console.log(`--- ${v.id} [${v.impact}] x${v.count}: ${v.help}`);
    for (const n of v.nodes) console.log(`      ${n.t}   ${n.html}`);
  }
  await cdp.shot(label.replace(/\W+/g, '_'));
  return violations;
}

const all = [];
await cdp.send('Page.navigate', { url: BASE + '/' });
await sleep(7000);
all.push(['initial', await runAxe('initial')]);

