const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const PORT = 9350;
const chrome = spawn('chromium', ['--headless=new','--no-sandbox','--disable-gpu','--disable-dev-shm-usage','--window-size=1440,960',`--remote-debugging-port=${PORT}`,`--user-data-dir=${path.join(os.tmpdir(),'probe3-'+process.pid)}`,'about:blank'], { stdio: 'ignore' });
for (let i=0;i<60;i++){ try { const r = await fetch(`http://127.0.0.1:${PORT}/json/version`); if (r.ok) break; } catch {} await sleep(500); }
const targets = await (await fetch(`http://127.0.0.1:${PORT}/json/list`)).json();
const ws = new WebSocket(targets.find((t) => t.type === 'page').webSocketDebuggerUrl);
await new Promise((res) => ws.addEventListener('open', res, { once: true }));
let id = 0; const pending = new Map();
ws.addEventListener('message', (e) => { const m = JSON.parse(e.data); if (m.id && pending.has(m.id)) { const {resolve,reject}=pending.get(m.id); pending.delete(m.id); m.error?reject(new Error(m.error.message)):resolve(m.result); } });
const send = (method, params={}) => new Promise((resolve,reject)=>{ const i=++id; pending.set(i,{resolve,reject}); ws.send(JSON.stringify({id:i,method,params})); });
const ev = async (expr) => { const r = await send('Runtime.evaluate', { expression: expr, returnByValue: true, awaitPromise: true }); if (r.exceptionDetails) throw new Error(r.exceptionDetails.exception?.description); return r.result?.value; };
await send('Page.enable'); await send('Runtime.enable');
await send('Page.navigate', { url: 'http://127.0.0.1:8787/?cmp=e-rara%3A8562848,e-rara%3A8602092' });
await sleep(8000);
await ev(AXE);
console.log(await ev(`(() => {
  const banners = [...document.querySelectorAll('body *')].filter(n => { try { return axe.commons.role.getRole(n) === 'banner'; } catch { return false; } });
  const info = banners.map(n => ({ tag: n.tagName, cls: n.className, role: n.getAttribute('role'), parent: n.parentElement?.tagName + '.' + n.parentElement?.className, parentRole: (()=>{try{return axe.commons.role.getRole(n.parentElement);}catch{return null}})() }));
  return JSON.stringify({ count: banners.length, info }, null, 1);
})()`));
// open the compare view and re-check
const box = await ev(`(() => { const n = document.querySelector('#compare-open'); if (!n) return null; n.scrollIntoView({block:'center',behavior:'instant'}); const r = n.getBoundingClientRect(); return {x: r.left + r.width/2, y: r.top + r.height/2}; })()`);
if (box) {
  const common = { x: Math.round(box.x), y: Math.round(box.y), button: 'left', clickCount: 1 };
  await send('Input.dispatchMouseEvent', { type: 'mouseMoved', ...common });
  await send('Input.dispatchMouseEvent', { type: 'mousePressed', ...common });
  await send('Input.dispatchMouseEvent', { type: 'mouseReleased', ...common });
}
await sleep(5000);
console.log(await ev(`(() => {
  const banners = [...document.querySelectorAll('body *')].filter(n => { try { return axe.commons.role.getRole(n) === 'banner'; } catch { return false; } });
  return JSON.stringify({ open: !!document.querySelector('#compare-view')?.hidden === false, count: banners.length, info: banners.map(n => ({ tag: n.tagName, cls: n.className, parent: n.parentElement?.className })) }, null, 1);
})()`));
ws.close(); chrome.kill('SIGKILL');

