/**
 * Prototype of the WCAG 2.5.3 sweep that will go into scripts/browser-check.mjs.
 * Checks: (1) the live page is clean, (2) a deliberately broken control is
 * detected (non-vacuous), (3) controls whose visible text is a real substring
 * are not flagged (no false positives).
 */
import { spawn } from 'node:child_process';
import os from 'node:os';
import path from 'node:path';

const SWEEP = `(() => {
  const tokens = (text) => String(text).toLowerCase()
    .replace(/\\([^()]*\\)/g, ' ')
    .replace(/[^\\p{L}\\p{N}]+/gu, ' ')
    .trim().split(/\\s+/).filter(Boolean);
  const containsRun = (name, label) => {
    const n = tokens(name);
    const l = tokens(label);
    if (l.length === 0) return true;
    for (let i = 0; i + l.length <= n.length; i += 1) {
      if (l.every((token, j) => token === n[i + j])) return true;
    }
    return false;
  };
  const attributeName = (node) => {
    const labelledby = node.getAttribute('aria-labelledby');
    if (labelledby) {
      const parts = labelledby.split(/\\s+/).map((id) => document.getElementById(id))
        .filter(Boolean).map((ref) => ref.innerText || ref.textContent || '');
      if (parts.join(' ').trim()) return parts.join(' ');
    }
    return node.getAttribute('aria-label') || '';
  };
  const selector = 'a[href], button, summary, [role="button"], [role="link"], [role="switch"], [role="checkbox"], [role="tab"], [role="menuitem"], input[type="submit"], input[type="button"], input[type="reset"]';
  const offenders = [];
  let scanned = 0;
  for (const node of document.querySelectorAll(selector)) {
    const name = attributeName(node);
    if (!name.trim()) continue;
    if (node.hidden || node.getClientRects().length === 0) continue;
    const visible = (node.innerText || '').replace(/\\s+/g, ' ').trim();
    if (!tokens(visible).length) continue;
    scanned += 1;
    if (!containsRun(name, visible)) {
      const id = node.id ? '#' + node.id : '';
      const cls = typeof node.className === 'string' && node.className ? '.' + node.className.split(' ')[0] : '';
      offenders.push(node.tagName.toLowerCase() + id + cls + ' | shown: "' + visible.slice(0, 60) + '" | name: "' + name.slice(0, 60) + '"');
    }
  }
  return { scanned, offenders };
})()`;

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const PORT = 9360;
const chrome = spawn('chromium', ['--headless=new', '--no-sandbox', '--disable-gpu', '--disable-dev-shm-usage', '--window-size=1440,960', `--remote-debugging-port=${PORT}`, `--user-data-dir=${path.join(os.tmpdir(), 'sweep-' + process.pid)}`, 'about:blank'], { stdio: 'ignore' });
