/* --- 8a. WCAG 2.5.3 (“Label in Name”) and the landmark list ------------ */
await cdp.send('Accessibility.enable');
const labelInName = await cdp.eval(LABEL_IN_NAME_SWEEP);
check(
  'every control named by aria-label still contains its own visible text (WCAG 2.5.3)',
  labelInName.count === 0,
  labelInName.count === 0 ? `${labelInName.scanned} named controls inspected` : labelInName.offenders.join(' | '),
);

// A sweep that cannot fail proves nothing: a synthetic mismatched control must
// be found by the very same snippet, then removed again.
const labelSweepSelfTest = await cdp.eval(`(() => {
  const probe = document.createElement('button');
  probe.type = 'button';
  probe.id = 'label-sweep-probe';
  probe.setAttribute('aria-label', 'Kartenausschnitte entkoppeln');
  probe.textContent = 'Ausschnitte gekoppelt';
  document.querySelector('#main').append(probe);
  const result = ${LABEL_IN_NAME_SWEEP};
  probe.remove();
  return result.offenders.some((entry) => entry.includes('#label-sweep-probe'));
})()`);
check(
  'the label-in-name sweep finds a synthetic mismatch (the check is not vacuous)',
  labelSweepSelfTest === true,
  `synthetic mismatch detected: ${labelSweepSelfTest}`,
);

const landmarks = await exposedLandmarks(cdp);
const landmarkCount = (role) => landmarks.filter((entry) => entry.role === role).length;
check(
  'the page exposes exactly one banner, one main and one contentinfo landmark',
  landmarkCount('banner') === 1 && landmarkCount('main') === 1 && landmarkCount('contentinfo') === 1,
  landmarks.map((entry) => `${entry.role}${entry.name ? `("${entry.name.slice(0, 18)}")` : ''}`).join(', '),
);

check(
  'compare view shows both sheets with real images and source links',
  panes.length === 2 && paneProblems.length === 0,
