/* Markers are real buttons with a strong cantonal-blue fill: the earlier white
   24 px pin blended into the swisstopo base map (which draws its own white
   junction circles), so the pins were invisible in practice. */
.map-marker {
  position: absolute;
  width: 30px;
  height: 30px;
  margin: -15px 0 0 -15px;
  padding: 0;
  border: 2px solid var(--zh-white);
  border-radius: 50%;
  background: var(--zh-blue);
  color: var(--zh-white);
  font-family: var(--zh-font-black);
  font-size: var(--zh-font-small);
  font-weight: 900;
  line-height: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  box-shadow: 0 0 0 1px var(--zh-black), 0 2px 5px rgb(0 0 0 / 45%);
}

.map-marker:hover {
  background: var(--zh-darkblue);
  color: var(--zh-white);
}

.map-marker.is-selected {
  background: var(--zh-cyan);
  color: var(--zh-black);
  z-index: 3;
  /* The 1.25 scale is part of the inline translate3d() in map.js – a transform
     here would be overridden by that inline style. */
  box-shadow: 0 0 0 2px var(--zh-white), 0 0 0 4px var(--zh-darkblue);
}

.map-marker.is-preview {
  background: var(--zh-darkblue);
  color: var(--zh-white);
  z-index: 4;
  box-shadow: 0 0 0 2px var(--zh-white), 0 0 0 4px var(--zh-cyan);
}

/* Cluster: one control for overlapping markers at the current zoom. Darker than
   a single pin so the number reads as “several maps”, not as one record. */
.map-marker.map-cluster {
  width: 34px;
  height: 34px;
  margin: -17px 0 0 -17px;
  background: var(--zh-darkblue);
  color: var(--zh-white);
  font-size: var(--zh-font-tiny);
  z-index: 2;
  box-shadow: 0 0 0 2px var(--zh-white), 0 0 0 4px var(--zh-darkblue), 0 2px 6px rgb(0 0 0 / 45%);
}

.map-marker.map-cluster:hover {
  background: var(--zh-black);
  color: var(--zh-white);
}

.map-marker.map-cluster.is-preview {
  background: var(--zh-cyan);
  color: var(--zh-black);
}

.map-marker:focus-visible {
